BEGIN;
UPDATE public.agent_configuration_catalog SET definition=$question_rule${"key": "productQuestionRules", "target": "policy", "type": "textarea", "label": "Perguntas e autorização de compra", "group": "Decisão comercial", "description": "Expressões normalizadas sem acentos. Uma referência numérica em uma pergunta não autoriza criar carrinho. Condições de compra exigem resolver a dúvida primeiro.", "default": "{\"questionPatterns\": [\"\\\\b(?:eh|tem|possui|usa|funciona|mede|pesa|custa|aceita|vem com)\\\\b\", \"\\\\b(?:qual|quais|quanto|quantos|como)\\\\b\", \"\\\\b(?:saber|duvida|confirma|confirmar|me diga|me fala)\\\\b\", \"\\\\be\\\\s+(?:automatico|manual|solar|original|novo|usado|quartz|quartzo|mineral|safira|resistente|de\\\\s+safira)\\\\b\"], \"commitPatterns\": [\"\\\\b(?:quero comprar|vou levar|pode fechar|pode montar|gere o carrinho|gerar o carrinho|adicione|adicionar|coloque|colocar)\\\\b\", \"\\\\bcomo\\\\s+(?:posso|podes|voce|voces|faz|fazer).{0,40}fechar\\\\b\"], \"conditionalPatterns\": [\"\\\\b(?:se|caso|antes de|so depois|depende|mas antes)\\\\b\", \"\\\\bnao\\\\s+(?:quero|vou|pode|adicione|coloque)\\\\b\"]}", "maxLength": 6000}$question_rule$::jsonb,updated_at=now() WHERE key='productQuestionRules';
COMMIT;
